/* Road centre-lines are a build-time OSRM snapshot. No map tiles, tracking, API key or live routing. */
const MAP_DAYS=[
  {id:'oct04',date:'10.04',title:'进山',subtitle:'取车 → Zion → Bryce → Hatch',color:'#9a5b3a'},
  {id:'oct05',date:'10.05',title:'从石柱到沙岩',subtitle:'Hatch → Bryce → Ken’s → Page',color:'#b28049'},
  {id:'oct06',date:'10.06',title:'大峡谷',subtitle:'Page → 南缘 → Flagstaff',color:'#355c58'},
  {id:'oct07',date:'10.07',title:'返程',subtitle:'Flagstaff → 66号公路 → LAS',color:'#607a76'}
];
const MAP_STOP={
  rental:['Hertz 租车中心','7135 Gilespie St, Las Vegas, NV 89119','取车 / 还车'],
  zion:['Canyon Overlook','Canyon Overlook Trailhead, Zion National Park','隧道东口步道'],
  sunset:['Bryce · Sunset Point','Sunset Point Parking, Bryce Canyon National Park','石柱日落'],
  hatch:['Hatch','Hatch, Utah','镇中心示意；民宿门牌不公开'],
  sunrise:['Bryce · Sunrise Point','Sunrise Point Parking, Bryce Canyon National Park','早晨徒步起点'],
  ken:['Ken’s Tours','36.9026,-111.4112','以已订时段为准'],
  home2:['Home2 · Page','681 Scenic View Rd, Page, AZ 86040','10月5日晚住宿'],
  horse:['马蹄湾停车场','Horseshoe Bend Parking Lot, Page, AZ','市政府停车场，年卡不抵停车费'],
  desert:['Desert View','Desert View Watchtower Parking, Grand Canyon','大峡谷东门观景区'],
  navajo:['Navajo Point','Navajo Point Parking, Grand Canyon National Park','东缘观景'],
  moran:['Moran Point','Moran Point Parking, Grand Canyon National Park','时间紧可略过'],
  grandview:['Grandview Point','Grandview Point Parking, Grand Canyon National Park','时间紧可略过'],
  mather:['Mather Point','Grand Canyon Visitor Center Parking Lot 2','游客中心停车后步行'],
  yavapai:['Yavapai Point','Yavapai Geology Museum Parking, Grand Canyon','日落路线终点 / 补拍路线折返点'],
  fairfield:['Fairfield East','1000 N Country Club Dr, Flagstaff, AZ 86004','10月6日晚住宿'],
  aspen:['Aspen Corner','Aspen Corner, N Snow Bowl Rd, Flagstaff, AZ','7日早晨看叶色'],
  seligman:['Seligman','22405 W Historic Route 66, Seligman, AZ','老66街区'],
  kingman:['Kingman','120 W Andy Devine Ave, Kingman, AZ','有时间才停'],
};
const MAP_TIMES={
  oct04:['09:30','约14:00 MDT','日落前','夜间入住'],
  oct05:['早晨出发','上午徒步','按订单签到','导览后入住'],
  oct06_direct:['08:40','09:00','12:30','13:40','14:15','可选','15:15','17:00–18:20','约20:20'],
  oct06_core:['08:40','09:00','12:30','13:40','14:15','可选','15:15','16:15前离开','17:15–19:50','约21:40'],
  oct07:['07:45','08:25','11:00','13:30 可选','17:00–17:30 目标']
};
let savedMapVariant='direct';try{savedMapVariant=localStorage.getItem('canyon-day6-route')==='core'?'core':'direct';}catch{}
let mapDay=4,mapVariant=savedMapVariant,mapLeg=0,mapView=null,mapPointer=null;
const mapPlan=()=>mapDay===4?'oct06_'+mapVariant:mapDay===2?'oct04':mapDay===3?'oct05':'oct07';
const mapLegs=()=>mapDay===6?['oct04','oct05','oct06_'+mapVariant,'oct07'].flatMap(id=>ROUTE_GEOMETRY[id]):ROUTE_GEOMETRY[mapPlan()];
function mapGeo(p){return [(p[0]+116)*185,(38-p[1])*235];}
function mapCoords(legs){return legs.flatMap(l=>l.line.map(mapGeo));}
function mapFit(legs){const points=mapCoords(legs),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const left=Math.min(...xs),top=Math.min(...ys),width=Math.max(...xs)-left,height=Math.max(...ys)-top;const pad=Math.max(22,Math.max(width,height)*(mapDay===6?.14:.09));const w=width+2*pad,h=height+2*pad;const ratio=window.innerWidth<=760?.88:1.45;if(w/h<ratio)return [left-pad-(h*ratio-w)/2,top-pad,h*ratio,h];return [left-pad,top-pad-(w/ratio-h)/2,w,w/ratio];}
function mapPath(line){return line.map((p,i)=>{const [x,y]=mapGeo(p);return (i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}).join(' ');}
function mapStopLabel(legs,index){const id=index?legs[index-1].to:legs[0].from;return id==='desert'&&mapDay===4&&mapVariant==='core'&&index===8?'Desert View · 日落和银心':MAP_STOP[id][0];}
function mapStopId(legs,index){return index?legs[index-1].to:legs[0].from;}
function mapStopPoint(legs,index){return index?legs[index-1].line.at(-1):legs[0].line[0];}
function mapLinks(from,to){const a=MAP_STOP[from],b=MAP_STOP[to];const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(a[1])+'&destination='+encodeURIComponent(b[1])+'&travelmode=driving';return `<a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">在 Google Maps 查看这一段 ↗</a>`;}
function routeMap(){const legs=mapLegs(),meta=MAP_DAYS[mapDay-2],selected=legs[Math.min(mapLeg,legs.length-1)];mapLeg=Math.min(mapLeg,legs.length-1);if(!mapView)mapView=mapFit(legs);const v=mapView.join(' ');const total=legs.reduce((n,l)=>n+l.km,0);return `<div class="page-heading map-heading"><div><p class="eyebrow">ROAD ATLAS / 自驾路线</p><h1>每一段路，<em>看得见。</em></h1><p>道路形状按已规划停靠点生成；点击路段或站点查看去向。地图不是实时导航，出发时仍以 Google Maps 和现场封路为准。</p></div><span class="map-edition">2026 · NV / UT / AZ</span></div><div class="map-day-picker" role="group" aria-label="选择自驾日期">${MAP_DAYS.map((d,i)=>`<button type="button" data-map-day="${i+2}" class="${mapDay===i+2?'active':''}" aria-pressed="${mapDay===i+2}"><span>${d.date}</span><strong>${d.title}</strong><small>${d.subtitle}</small></button>`).join('')}</div>${mapDay===4?`<div class="map-choice"><div><strong>10 月 6 日有两种走法</strong><p>5 日在 Page 拍到了银心，就直接南下；没拍到且天气允许，再折返 Desert View。</p></div><div class="map-choice-buttons" role="group" aria-label="10月6日路线"><button type="button" data-map-variant="direct" class="${mapVariant==='direct'?'active':''}" aria-pressed="${mapVariant==='direct'}">A · 看完日落直接去酒店</button><button type="button" data-map-variant="core" class="${mapVariant==='core'?'active':''}" aria-pressed="${mapVariant==='core'}">B · 折返补拍银心</button></div></div>`:''}<section class="road-atlas"><div class="atlas-map"><div class="atlas-map-top"><span class="atlas-map-title">${esc(meta.date)} · ${esc(meta.subtitle)}</span><span class="atlas-map-sub">约 ${total.toFixed(0)} km · 路网规划里程</span></div><svg id="route-svg" viewBox="${v}" role="img" aria-label="${esc(meta.date)} 自驾道路图，含 ${legs.length+1} 个停靠点"><defs><pattern id="terrain" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M0 20 Q10 5 20 20" fill="none" stroke="#b4b9a9" stroke-opacity=".2" stroke-width=".5"/></pattern><filter id="pin-shadow"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity=".25"/></filter></defs><rect x="-200" y="-300" width="2100" height="1800" fill="#e7e8df"/><rect x="-200" y="-300" width="2100" height="1800" fill="url(#terrain)"/><g class="map-state-lines"><path d="M360 235 L1300 235"/><path d="M360 235 L360 -280"/><text x="460" y="196">UTAH</text><text x="470" y="275">ARIZONA</text><text x="92" y="265">NEVADA</text></g><g class="map-road-halo">${legs.map(l=>`<path d="${mapPath(l.line)}"/>`).join('')}</g><g class="map-roads">${legs.map((l,i)=>`<path class="map-road ${l.from==='yavapai'&&l.to==='desert'?'backtrack':''} ${i===mapLeg?'selected':''}" data-map-leg="${i}" d="${mapPath(l.line)}"><title>${esc(MAP_STOP[l.from][0]+' → '+MAP_STOP[l.to][0])}</title></path>`).join('')}</g><g class="map-pins">${Array.from({length:legs.length+1},(_,i)=>{const point=mapStopPoint(legs,i),[x,y]=mapGeo(point),id=mapStopId(legs,i),special=id==='desert'&&mapVariant==='core'&&mapDay===4&&i===8;return `<g class="map-pin ${special?'backtrack-pin':''}" data-map-stop="${i}" tabindex="0" role="button" aria-label="第${i+1}站 ${esc(mapStopLabel(legs,i))}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><circle r="9"/><text text-anchor="middle" dominant-baseline="central">${i+1}</text></g>`}).join('')}</g></svg><div class="map-controls"><button type="button" data-map-zoom="in" aria-label="放大地图">＋</button><button type="button" data-map-zoom="out" aria-label="缩小地图">－</button><button type="button" data-map-zoom="fit" aria-label="显示完整路线">◎</button></div><div class="map-legend"><span><i></i> 当天自驾</span>${mapDay===4&&mapVariant==='core'?'<span><i class="return"></i> 回头路</span>':''}<span>拖动 / 滚轮缩放</span></div></div><aside class="atlas-detail"><div class="atlas-detail-head"><small>第 ${mapLeg+1} 段 / 共 ${legs.length} 段</small><h2>${esc(MAP_STOP[selected.from][0])}<span>→</span>${esc(MAP_STOP[selected.to][0])}</h2><p>${selected.from==='yavapai'&&selected.to==='desert'?'这段是折返：先从西侧观景区开回东门，再在 Desert View 看日落、等天黑拍银心。':esc(MAP_STOP[selected.to][2])}</p><div class="atlas-distance"><strong>${selected.km.toFixed(1)}<small>km</small></strong><span>路网约 ${selected.minutes} 分钟<br>未计停车、排队与实时路况</span></div>${mapLinks(selected.from,selected.to)}</div><div class="atlas-stop-scroll"><ol class="atlas-stops">${Array.from({length:legs.length+1},(_,i)=>{const id=mapStopId(legs,i),time=MAP_TIMES[mapPlan()][i];return `<li><button type="button" data-map-stop="${i}" class="${i===mapLeg+1?'active':''}"><span class="atlas-stop-number">${String(i+1).padStart(2,'0')}</span><span class="atlas-stop-copy"><strong>${esc(mapStopLabel(legs,i))}</strong><small>${esc(time)} · ${esc(MAP_STOP[id][2])}</small></span></button></li>`}).join('')}</ol></div></aside></section><div class="atlas-footnotes">${mapDay===4?mapVariant==='core'?'<p><strong>折返究竟多远？</strong>Yavapai → Desert View 约 38 km / 44 分钟；与直接去 Fairfield 相比，整晚约多开 31 km、约多 31 分钟。这还不包含在 Desert View 等到天黑、拍照的时间。若当天云多、疲劳或 5 日已经拍到，就切回 A。</p><p><strong>时间接法：</strong>16:15 前从 Yavapai 出发，争取 17:15 到 Desert View；18:04 左右日落，19:29 左右天文暮光结束，约 19:30–19:50 拍摄，再经 Cameron 去 Flagstaff。观景塔室内会关，室外区域与东门夜间开放；临时路况仍以园方公告为准。</p>':'<p><strong>直接南下：</strong>17:00 到 Yavapai，18:04 左右看日落，18:20 左右从南门离园去 Flagstaff。这样无需沿东缘道路回开；若 5 日 Page 已拍成，这是更轻松的一条线。</p>':''}<p>路形来自 OSRM 路网快照，站点是行程导航目的地；实时行车、道路封闭、停车与运营时间请以当地管理方和 Google Maps 为准。Hatch 地图只标镇中心，不显示私人住宿门牌。</p></div>`;}
function drawRouteMap(){const root=document.querySelector('#route-svg');if(root&&mapView)root.setAttribute('viewBox',mapView.join(' '));}
function chooseMapDay(next){if(![2,3,4,5,6].includes(next))return;mapDay=next;mapLeg=0;mapView=null;render();window.scrollTo({top:0,behavior:'instant'});}
function chooseMapVariant(next){if(!['direct','core'].includes(next))return;mapVariant=next;try{localStorage.setItem('canyon-day6-route',next);}catch{}applyDay6Variant();mapLeg=0;mapView=null;render();}
function selectMapLeg(next){mapLeg=Math.max(0,Math.min(next,mapLegs().length-1));const pos=window.scrollY;render();window.scrollTo(0,pos);}
function zoomRouteMap(factor){if(!mapView)return;const [x,y,w,h]=mapView,nw=w*factor,nh=h*factor;mapView=[x+(w-nw)/2,y+(h-nh)/2,nw,nh];drawRouteMap();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-map-day],[data-map-variant],[data-map-leg],[data-map-stop],[data-map-zoom]');if(!b)return;if(b.dataset.mapDay!==undefined)chooseMapDay(+b.dataset.mapDay);else if(b.dataset.mapVariant)chooseMapVariant(b.dataset.mapVariant);else if(b.dataset.mapLeg!==undefined)selectMapLeg(+b.dataset.mapLeg);else if(b.dataset.mapStop!==undefined)selectMapLeg(Math.max(0,+b.dataset.mapStop-1));else if(b.dataset.mapZoom==='fit'){mapView=mapFit(mapLegs());drawRouteMap();}else zoomRouteMap(b.dataset.mapZoom==='in'?.75:1.33);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-pin')){e.preventDefault();selectMapLeg(Math.max(0,+e.target.dataset.mapStop-1));}});
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('#route-svg');if(!svg||e.target.closest('[data-map-leg],[data-map-stop]'))return;mapPointer={x:e.clientX,y:e.clientY,view:[...mapView]};svg.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!mapPointer)return;const svg=document.querySelector('#route-svg');if(!svg)return;const r=svg.getBoundingClientRect(),v=mapPointer.view;mapView=[v[0]-(e.clientX-mapPointer.x)*v[2]/r.width,v[1]-(e.clientY-mapPointer.y)*v[3]/r.height,v[2],v[3]];drawRouteMap();});
document.addEventListener('pointerup',()=>{mapPointer=null;});
document.addEventListener('wheel',e=>{const svg=e.target.closest('#route-svg');if(!svg)return;e.preventDefault();zoomRouteMap(e.deltaY<0?.9:1.1);},{passive:false});

/* The day page and print view use the same branch as the map. The original A
   schedule is kept intact, so changing B back to A never loses checkmarks. */
const DAY6_DIRECT={events:DAYS[4].events,intro:DAYS[4].intro,alerts:DAYS[4].alerts,fallback:DAYS[4].fallback,tag:DAYS[4].tag,drive:DAYS[4].drive};
const DAY6_CORE_EVENTS=[...DAY6_DIRECT.events.slice(0,8),
  ev('14:15','15:05','see','Moran / Grandview：最多选一站','把这段当作可删项，不逐个打卡。','moran',['16:15 前离开 Yavapai 是后面折返的关键；入园或午餐耽误，直接去 Mather。'],{optional:true,secondPlace:'grandview'}),
  ev('15:05','15:55','see','Mather Point + 崖顶短走','从 Visitor Center 正式停车区走到观景台；不下到 Ooh Aah。','mather',['控制在 50 分钟内，提前看一下天气和西南天空。']),
  ev('15:55','16:15','see','Yavapai 短停，决定是否折返','这里只看下午的峡谷；B 线的日落留到 Desert View。','yavapai',['若已过 16:15、天阴或司机疲劳，当场切回 A 线。','吃掉提前备好的三明治，不把晚餐押在 21:40 之后。']),
  ev('16:15','17:15','drive','沿 AZ-64 折返 Desert View','约 38 km / 路网 44 分钟；另外留停车余量。','desert',['这是折返，不是顺路经过：从大峡谷村附近开回东门。','不急驶；如果 Google Maps 给出的到达时间太晚，改走 A 线。'],{origin:'yavapai'}),
  ev('17:15','18:15','see','Desert View 等日落','约 18:04 日落。先在停车场确认回车路线，再沿正式步道找安全拍摄位置。','desert',['塔内 / 上层有营业时段；日落和夜间只依赖室外区域。','西南低空银心与峡谷同框不保证；园方指出观景塔可作银心前景。'],{source:'desertNight'}),
  ev('18:15','19:30','rest','暮光、布置构图与吃简餐','等天色暗下来；提前辨认西南地平线、回车路线和脚下地形。','desert',['用红光灯，注意其他摄影者。','晚饭是下午买好的食物，不指望已关门的 Desert View Market。','云层、风或低空遮挡不合适，别硬等到 19:30。']),
  ev('19:30','19:50','see','低空银心 · 试拍 20 分钟','这是机会窗口，不保证一定拍到；先拍稳一张，再考虑多张堆栈。','desert',['16mm F1.8：RAW、10–15 秒、ISO 1600–3200 起步；试拍后放大看星点。','只在正式公共区域拍，不走向崖边或黑暗小路。'],{source:'desertNight'}),
  ev('19:50','21:45','drive','Desert View → Fairfield East','从东门方向经 Cameron 南下，夜间路况以 Google Maps 为准。','fairfield',['这是补拍方案比 A 线晚到酒店的主要代价。','路边野生动物与疲劳风险比节省几十分钟更重要，困了就休息。'],{origin:'desert'}),
  ev('21:45','22:15','stay','入住、吃备好的晚餐','今晚不再安排 Flagstaff 市中心；酒店见到前台时核对明晨早餐和停车。','fairfield')
];
DAY6_CORE_EVENTS.slice(8).forEach((e,i)=>{e.id=`d4-core-${i}`;e.steps=Array.isArray(e.steps)?e.steps:[];e.zone=e.zone||DAYS[4].zone;e.endZone=e.endZone||e.zone;});
function applyDay6Variant(){const d=DAYS[4];if(mapVariant==='core'){
  d.events=DAY6_CORE_EVENTS;d.intro='今天仍从东门进、由东向西看。到 Yavapai 短停后，沿 AZ-64 折返约 38 km 回 Desert View；在那里看约 18:04 的日落、等天黑拍低空银心，再经 Cameron 去 Flagstaff。只在 5 日没拍到且天气、体力允许时走这条。';
  d.alerts=['B 线不是顺路：Yavapai → Desert View 是实打实的回头路，约 38 km / 44 分钟，另计停车与等待。','16:15 前离开 Yavapai，争取 17:15 到 Desert View；晚于这个节点就改 A 线。','18:04 左右日落、19:29 左右天文暮光结束；银心很低，能否拍到取决于西南地平线和天气。','市场和塔内按营业时间关闭；室外观景区及东门通常 24 小时开放，临时封路以 NPS 当天公告为准。'];
  d.fallback='下午延误先删 Moran / Grandview。16:15 前没能离开 Yavapai、云多、风大或司机疲劳，切换 A 线直接南下 Flagstaff。';d.tag='Desert View 日落 · 低空银心';d.drive='约5.5小时 · 含折返与园内移动';
}else Object.assign(d,DAY6_DIRECT);}
