const STAR6_CORE={title:'Desert View · 同一地点看日落与银心',place:'Desert View Watchtower 室外观景区',address:'Desert View Watchtower Parking, Grand Canyon National Park, AZ',distance:'Yavapai 折返约 38 km；拍摄后到 Fairfield East 路网约 127 km',window:'10/6 17:15 就位；约18:04日落，19:30–19:50尝试低空银心',moon:STARS[4].moon,reality:'这条 B 线不用放弃大峡谷日落，代价是先从 Yavapai 沿 AZ-64 开回东门。银心在西南低空，塔可以作前景；峡谷和银心同时漂亮入镜不能保证。拍摄后再开近 2 小时夜路到酒店。',subjects:[['第一张 · 日落','先在合法室外观景区拍峡谷和塔的晚霞，不需登塔。'],['第二张 · 银心','天黑后用星图确认西南低空；塔作前景，避开灯光与悬崖边缘。'],['拍不到也不白跑','天鹅座高处银河、星轨、星空与塔的剪影同样可以用 16mm 拍。']],plan:['16:15 前离开 Yavapai；预计 17:15 左右到 Desert View，停车后先看正式步道、护栏和回车路线。','18:04 前拍日落。塔内或上层会在傍晚关闭，不把登塔作为计划前提。','18:15–19:29 吃提前买好的简餐、调相机与辨认西南方；19:30–19:50 试拍银心，太低或有云就转拍高处星带。','19:50 左右收车，经 Cameron 前往 Fairfield East；累了立刻缩短拍摄，不为星空疲劳驾驶。'],camera:STARS[4].camera,workflow:STARS[4].workflow,safety:'大峡谷东门与公园室外区通常 24 小时开放，但临时天气封路仍可能发生。只在指定停车区及正式步道活动，结伴、穿保暖层、用红光灯，不为取景靠近无护栏边缘；野生动物不可保证绝对不会遇到。',sources:['https://www.nps.gov/grca/planyourvisit/desert-view.htm','https://www.nps.gov/grca/learn/nature/night-skies.htm','https://www.timeanddate.com/sun/@5296409?month=10&year=2026','https://www.nps.gov/grca/planyourvisit/conditions.htm']};
Object.assign(STARS[4],{reality:'A 线先在 Yavapai 看日落，再直接南下 Flagstaff；到酒店较早，晚些还可在合法停车区拍天鹅座银河星带和星轨。若 5 日 Page 没拍到银心，不必放弃大峡谷日落：切换 B 线折返 Desert View，但会晚到酒店。',subjects:[['A · 轻松回酒店','Yavapai 日落后南下，晚间有体力再去 Peak View 拍星带。'],['B · 补拍银心','在自驾地图切 B 线：16:15 离开 Yavapai，回 Desert View 同晚看日落与拍星。'],['拍星不止银心','高处银河、北天星轨、山影都能发挥 16mm 广角优势。']],plan:['当前 A 线：18:04 左右在 Yavapai 看日落，约 20:20 到 Fairfield East；先吃饭再决定是否去 Peak View。','想拍银心则打开“自驾地图”切 B 线：折返 Desert View，在那里看日落和等天黑；不会去 Flagstaff 的早场机位。','若天气差、疲劳或时间已晚，保留 A 线，别夜里加无名野外停车点。']});
Object.assign(STARS[4],{title:'Flagstaff · 晚场星带与星轨',window:'A 线约22:10–22:55可拍星带；想拍银心请切换 B 线到 Desert View'});
const tripDaily=daily,tripOverview=overview,tripKit=kit;
daily=function(){const html=tripDaily().replace('今天，照着这页走。','当天几点走、去哪停。');if(day!==4)return html;const card=`<div class="day6-route-picker"><div><strong>今晚走哪条？</strong><p>${mapVariant==='core'?'B · 折返 Desert View 看日落、拍星；晚到 Flagstaff。':'A · Yavapai 看日落后直接去 Flagstaff；这是省力默认线。'}</p></div><div><button type="button" data-map-variant="direct" class="${mapVariant==='direct'?'active':''}">A · 直接南下</button><button type="button" data-map-variant="core" class="${mapVariant==='core'?'active':''}">B · 折返拍星</button><a href="#map">在地图上看回头路 ↗</a></div></div>`;return html.replace('<div class="daily-layout">',card+'<div class="daily-layout">');};
overview=function(){return tripOverview().replace('非地理比例地图。Hatch 当晚住宿后','路线顺序示意；<a href="#map">打开可交互自驾地图</a>查看真实路形和 10/6 折返。Hatch 当晚住宿后').replace('一圈主线，不再绕回 Cedar City。','从 Vegas 出发，绕过峡谷、回到 Vegas。').replace('这一趟，不再到处翻聊天记录。<br>什么时候出门、在哪里停下、今晚睡在哪，<br>都在这份随身旅行手册里。','几点出门、在哪停车、今晚住哪里。<br>出发前翻开当天那页，路上少做几次临时决定。').replace('五晚，都安排好了','查看五晚住宿').replace('六天，六种风景。','按日期，直接找安排。').replace('给路上的你。','路上用得上的功能。');};
kit=function(){return tripKit().replace('羚羊谷导览、马蹄湾停车另算。','Zion、Bryce 与大峡谷普通入园不需预订时段；出示有效且适用的 America the Beautiful 年卡和证件。羚羊谷导览已单独购买/预约，马蹄湾停车由 Page 市收取，年卡不能抵。').replace('（仅本机）','（登录后可同步）').replace('地图、电话和官方链接仍需网络。','自驾路线图与道路快照可离线看；Google Maps 导航、电话和官方链接仍需网络。');};
const atlasBody=routeMap;
function fullRouteMap(){
  const ids=['oct04','oct05','oct06_'+mapVariant,'oct07'];
  const groups=ids.map((id,i)=>({meta:MAP_DAYS[i],legs:ROUTE_GEOMETRY[id],day:i+2}));
  const legs=groups.flatMap(g=>g.legs);
  if(!mapView)mapView=mapFit(legs);
  const total=legs.reduce((n,l)=>n+l.km,0);
  const places=[['rental','Las Vegas',17,22],['zion','Zion',13,-18],['hatch','Hatch',14,-15],['home2','Page',17,22],['desert','大峡谷',15,-18],['fairfield','Flagstaff',14,22]];
  const labels=places.map(([id,name,dx,dy])=>{const leg=legs.find(l=>l.from===id)||legs.find(l=>l.to===id);const p=leg.from===id?leg.line[0]:leg.line.at(-1);const [x,y]=mapGeo(p);return `<g class="overview-place" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><circle r="6"/><text x="${dx}" y="${dy}">${esc(name)}</text></g>`;}).join('');
  return `<div class="page-heading map-heading"><div><p class="eyebrow">ROAD ATLAS / 自驾路线</p><h1>绕过峡谷，<em>回到 Vegas。</em></h1><p>这是 10 月 4–7 日的自驾环线。按颜色看每天怎么走，点开日期再看每一段路和导航地址。路形是规划快照，不含实时交通。</p></div><span class="map-edition">2026 · NV / UT / AZ</span></div>
  <div class="map-day-picker map-day-picker-all" role="group" aria-label="选择自驾日期"><button type="button" data-map-day="6" class="active" aria-pressed="true"><span>10.04—10.07</span><strong>全程总览</strong><small>四天自驾环线</small></button>${MAP_DAYS.map((d,i)=>`<button type="button" data-map-day="${i+2}" aria-pressed="false"><span>${d.date}</span><strong>${d.title}</strong><small>${d.subtitle}</small></button>`).join('')}</div>
  <div class="map-choice"><div><strong>10 月 6 日怎么走？</strong><p>${mapVariant==='core'?'B 线：Yavapai 折返 Desert View 看日落、等银心，再去 Flagstaff。':'A 线：Yavapai 看日落后直接去 Flagstaff。'} 切换会同步当天行程。</p></div><div class="map-choice-buttons" role="group" aria-label="10月6日路线"><button type="button" data-map-variant="direct" class="${mapVariant==='direct'?'active':''}" aria-pressed="${mapVariant==='direct'}">A · 直接南下</button><button type="button" data-map-variant="core" class="${mapVariant==='core'?'active':''}" aria-pressed="${mapVariant==='core'}">B · 折返拍星</button></div></div>
  <section class="overview-atlas"><div class="atlas-map overview-map"><div class="atlas-map-top"><span class="atlas-map-title">LAS → ZION → BRYCE → PAGE → GRAND CANYON → LAS</span><span class="atlas-map-sub">路网约 ${total.toFixed(0)} km · 含各天景区内移动</span></div><svg id="route-svg" viewBox="${mapView.join(' ')}" role="img" aria-label="10月4日至7日完整自驾环线，10月6日${mapVariant==='core'?'折返 Desert View':'直接去 Flagstaff'}"><defs><pattern id="terrain" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M0 20 Q10 5 20 20" fill="none" stroke="#b4b9a9" stroke-opacity=".2" stroke-width=".5"/></pattern><filter id="pin-shadow"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity=".25"/></filter></defs><rect x="-200" y="-300" width="2100" height="1800" fill="#e7e8df"/><rect x="-200" y="-300" width="2100" height="1800" fill="url(#terrain)"/><g class="map-state-lines"><path d="M360 235 L1300 235"/><path d="M360 235 L360 -280"/><text x="460" y="196">UTAH</text><text x="470" y="275">ARIZONA</text><text x="92" y="265">NEVADA</text></g><g class="map-road-halo">${legs.map(l=>`<path d="${mapPath(l.line)}"/>`).join('')}</g><g class="overview-roads">${groups.map(g=>`<g style="--route-color:${g.meta.color}">${g.legs.map(l=>`<path d="${mapPath(l.line)}" class="overview-road ${l.from==='yavapai'&&l.to==='desert'?'backtrack':''}"><title>${esc(g.meta.date+' · '+MAP_STOP[l.from][0]+' → '+MAP_STOP[l.to][0])}</title></path>`).join('')}</g>`).join('')}</g><g aria-hidden="true">${labels}</g></svg><div class="map-controls"><button type="button" data-map-zoom="in" aria-label="放大地图">＋</button><button type="button" data-map-zoom="out" aria-label="缩小地图">－</button><button type="button" data-map-zoom="fit" aria-label="显示完整路线">◎</button></div><div class="map-legend"><span>四种颜色 = 四天</span>${mapVariant==='core'?'<span><i class="return"></i> 10/6 回头路</span>':''}<span>拖动 / 缩放</span></div></div></section>
  <div class="overview-route-days">${groups.map(g=>{const km=g.legs.reduce((n,l)=>n+l.km,0);return `<button type="button" data-map-day="${g.day}" class="overview-route-day" style="--route-color:${g.meta.color}"><span class="overview-route-date">${g.meta.date}</span><strong>${g.meta.title}</strong><small>${g.meta.subtitle}</small><span class="overview-route-km">约 ${km.toFixed(0)} km · 查看路段与导航 ↗</span></button>`;}).join('')}</div><p class="overview-map-note">10 月 2–3 日在 Las Vegas 市区，不计入这张自驾图。景区内停车、临时封路、加油和实际车程请出发前再查；Hatch 只显示镇中心，民宿门牌不公开。</p>`;
}
routeMap=function(){if(mapDay===6)return fullRouteMap();let html=atlasBody().replace('整晚约多开 31 km、约多 31 分钟','整晚约多开 15 km、约多 31 分钟');const ids=mapDay===4?['home2','desert','yavapai','fairfield']:mapDay===2?['rental','zion','sunset','hatch']:mapDay===3?['hatch','sunrise','ken','home2']:['fairfield','aspen','seligman','kingman','rental'];const labels=ids.map((id,i)=>{const leg=mapLegs().find(l=>l.from===id)||mapLegs().find(l=>l.to===id),p=leg.from===id?leg.line[0]:leg.line.at(-1),[x,y]=mapGeo(p);return `<text class="map-major-label" x="${(x+(i%2?-16:16)).toFixed(1)}" y="${(y+(i%2?-16:24)).toFixed(1)}" text-anchor="${i%2?'end':'start'}">${esc(MAP_STOP[id][0])}</text>`}).join('');html=html.replace('</svg>',`<g aria-hidden="true">${labels}</g></svg>`).replace('<div class="map-day-picker"','<div class="map-day-picker map-day-picker-all"').replace('</div><section class="road-atlas">','<button type="button" data-map-day="6" aria-pressed="false"><span>10.04—10.07</span><strong>全程总览</strong><small>四天自驾环线</small></button></div><section class="road-atlas">');return html+`<section class="atlas-sources"><div><span class="eyebrow">CHECK BEFORE DEPARTURE</span><h2>上路前，核对这四件事。</h2><p>你已有国家公园年卡：确认卡种为有效的 America the Beautiful、有效期及持卡人证件。普通入园无需额外预约，但特定项目和停车另计。</p></div><div><a href="https://www.nps.gov/grca/planyourvisit/fees.htm" target="_blank" rel="noopener noreferrer">大峡谷入园 / 不需预约 ↗</a><a href="https://www.nps.gov/grca/planyourvisit/desert-view.htm" target="_blank" rel="noopener noreferrer">Desert View 夜间开放 ↗</a><a href="https://www.nps.gov/grca/learn/nature/night-skies.htm" target="_blank" rel="noopener noreferrer">NPS 拍星位置建议 ↗</a><a href="https://www.nps.gov/glca/planyourvisit/horseshoe-bend.htm" target="_blank" rel="noopener noreferrer">马蹄湾停车另付 ↗</a></div></section>`;};
const routeMapWithDayPicker=routeMap;
routeMap=function(){
  let html=routeMapWithDayPicker();
  if(mapDay===6)return html;
  const picker=html.indexOf('class="map-day-picker');
  const end=html.indexOf('</div>',picker);
  const allButton='<button type="button" data-map-day="6" aria-pressed="false"><span>10.04—10.07</span><strong>全程总览</strong><small>四天自驾环线</small></button>';
  if(html.slice(picker,end).includes('data-map-day="6"'))return html;
  html=html.replace(allButton,'');
  const insertAt=html.indexOf('</div>',picker);
  return html.slice(0,insertAt)+allButton+html.slice(insertAt);
};
